-- GENERATED by `wfi generate` from data/quest/quest-0098.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [98021] = { "Viaggio verso Sentinel Hill", "Fai rapporto a Gryan Stoutmantle, a Sentinel Hill, Westfall.", "Se vuoi cominciare a fare del bene nel nostro mondo, ti consiglio di presentarti a un uomo di nome Gryan Stoutmantle, a Westfall, a sud, nell'insediamento noto come Sentinel Hill. La sua gente ha bisogno di aiuto.\n\nDopo essere <giunto/giunta> qui da un altro piano d'esistenza, i problemi delle nostre terre potranno sembrarti piccoli. Ti assicuro che l'aiuto che darai a chi ne è colpito significa tutto per loro, e ne uscirai più forte grazie alle tue fatiche.\n\nBuona fortuna là fuori, <avventuriero/avventuriera>!", nil, "Sono mesi che supplico Stormwind di mandare aiuti e lui mi manda un elfo mingherlino? Be', chi mendica non può scegliere, suppongo.\n\n<Benvenuto/Benvenuta> a Westfall, {class}. Vediamo se riusciamo a metterti al lavoro.", 0xc1c4216f, 0x617304a7, 0x0210f242, nil, 0x0fdf4331, "...m." },
  [98025] = { "RICERCATA: Jai'vhanel", "Trova e uccidi la civetta nota come Jai'vhanel e prendi una delle sue piume. La civetta nera è stata vista l'ultima volta a nord delle rovine di Ameth'Aran, ai piedi della montagna. Riferisci la morte di Jai'vhanel alla Sentinel Glynda Nal'Shea, ad Auberdine.", "Attenzione!\n\nÈ offerta una ricompensa per la morte della civetta \"Jai'vhanel\", nota anche come \"Piumaspada\".\n\nPurtroppo questa civetta è impazzita e ha cominciato ad attaccare i viandanti lungo la strada vicino ad Auberdine.\n\nJai'vhanel è stata vista l'ultima volta a nord delle rovine di Ameth'Aran, ai piedi della montagna. Riportate una delle sue piume nere come il giaietto come prova della sua morte.\n\nLa ricompensa per questa taglia va richiesta alla Sentinel Glynda Nal'Shea, ad Auberdine.\n\nil consiglio del villaggio di Auberdine", "Salute, {class}. In cosa possono assisterti le sentinelle oggi? Forse sei qui per informarti sulla taglia su Jai'vhanel?", "È bello sapere che il problema è stato risolto, ma mi rattrista che non si sia trovata un'altra via. Jai'vhanel era stata una sorta di guardiana di questa zona per molto tempo, e non so cosa possa averla spinta verso la follia.\n\nIn ogni caso, grazie per il tuo servizio oggi, {class}. Le strade per Auberdine sono di nuovo sicure.", 0x85ab0f27, 0x9af9befe, 0x3578bfb5, 0x84f21aff, 0xc148bf34, "....." },
  [98027] = { nil, "Consegna la Crescent Necklace a Maliynn, ad Astranaar.", "<La collana d'argento che hai tra le mani brilla dolcemente mentre la esamini. La piccola forma a falce di luna somiglia ad altri simboli degli elfi della notte che hai già visto.\n\nGirando la collana trovi una piccola iscrizione: \"Alor'lormah, Maliynn\". Forse appartiene a Maliynn, ad Astranaar?>", nil, nil, nil, 0x8ae5ee49, 0x28957527, nil, nil, "m..mm" },
  [98028] = { nil, "Porta il Clouded Water Globe a Onu, al Grove of the Ancients di Darkshore.", "Tutto ciò che resta del potente elementale è un globo di quella che sembra acqua pura, offuscata da una sostanza sconosciuta. I bordi della sfera sembrano limpidi finché non la giri: come se la nube ti impedisse attivamente di guardarci dentro.\n\nQualunque cosa le sia accaduta, e sia accaduta alle rovine che custodiva, è ancora attiva in qualche modo.\n\nSolo Onu, l'Ancient of Lore al Grove of the Ancients, molto più a sud, potrebbe saperne di più.", nil, nil, nil, 0xd906839f, 0x53a26984, nil, nil, "m..mm" },
  [98042] = { "È tutto un gioco finché...", "Ottieni un Peerless Eye da un Twilight Disciple o un Twilight Thug al Master's Glaive, a Darkshore, e trova qualcuno ad Auberdine disposto a prenderlo.", "<Mentre strappi l'unica pagina dal Twilight Tome, una voce minacciosa ti invade la mente, non invitata.>\n\nHanno fallito.\n\nSarai <dimenticato/dimenticata>.\n\nPerderanno l'occhio che hanno ottenuto.", nil, nil, 0x780af214, 0x29e68b4e, 0x10cc5e5e, nil, nil, "...mm" },
  [98046] = { "La corona della terra", "Porta il Drained Vessel a Lariia, nel Temple of the Moon di Darnassus.", "<Lo sguardo dell'Arch Druid Fandral Staghelm si stringe.>\n\nSei ancora qui?\n\nPrendi la fiala e sparisci dalla mia vista, {class}. È chiaro che le mie risposte non si trovano nelle acque, proprio come prima.\n\nForse una delle sacerdotesse del Temple of the Moon, a sud, se ne sbarazzerà.\n\n<Fandral distoglie lo sguardo e smette di parlarti.>\n\nDevo cercare altrove, se si vuole che funzioni...", "Come posso aiutarti?", "Non badare all'Arch Druid, {name}. Porta il peso di molte cose in assenza di Malfurion.\n\nAspetta! Nella fiala restano ancora alcune gocce! Forse è per questo che il suo incantesimo è fallito?", 0x6a9c354f, 0xfa735665, 0x87e3b8dc, 0xa26e2aed, 0x8094bf8b, "....." },
  [98059] = { "Il tesoro di Hillsbrad", "Poni la Sealed Company Request che ti è stata data sul tavolo della contabilità, nella town hall di Hillsbrad.", "Il consiglio di Hillsbrad non ha risposto alle lettere del nostro nuovo magistrato. L'ultima notizia che ho strappato a un mercante di passaggio dalla città non giustifica affatto il loro silenzio.\n\nChiediamo solo un piccolo plotone, eppure mi dicono che diverse baliste d'assedio giacciono in condizioni perfette dentro un recinto murato.\n\nEntra nel loro municipio come un cittadino che riconsegna un modulo del censimento, e posa questo per bene sul tavolo della contabilità.\n\nTorna da me quando avrai fatto.", nil, nil, 0x741522bc, 0xd8226166, 0x3f1e8fb4, nil, nil, "...mm" },
  [98065] = { "La corona della terra", "Porta i Moonwell Remnants a Tyrande Whisperwind, nel Temple of the Moon di Darnassus.", "Devi portarla subito a Tyrande! La trasferirò per te in un contenitore più cerimoniale.\n\nNon avere paura. L'High Priestess di Elune è severa ma gentile. Protegge chiunque entri a Darnassus e porta a tutti la luce della nostra dea.\n\nSarà felice di ricevere quest'acqua sacra. La troverai proprio sopra di noi.", "Esponi la tua richiesta. Ho una città da governare e un popolo da guidare.", "Staghelm ha fatto molto in assenza del mio amato, ma non è Malfurion. E non è lui a gestire gli affari di Darnassus: quel fardello è soltanto mio.\n\n<Il volto di Tyrande si distende.>\n\nTi chiedo scusa. Come probabilmente avrai visto, abbiamo molte sfide da superare.\n\nPer ora Fandral è l'Arch Druid, e ti chiedo di rispettare il suo rango. Ma le sue faccende riguardano il druidismo, e le mie non solo Elune, ma anche il guidare il nostro popolo secondo la sua volontà.\n\nOgni goccia di quest'acqua è benedetta dalla nostra dea. Ti ringrazio per averla salvata.", 0x6a9c354f, 0x283abfd9, 0x13bb30c2, 0x073bf605, 0xf8575459, "....." },
  [98067] = { "Gli occhi delle Sentinels", "Poni delle Sentinel Owls all'ingresso delle profondità di Cenarion Hold, alla banca di Darnassus, alla locanda della Craftsman's Terrace e alla porta della città per la Sentinel Dalia Sunblade, nel Temple of the Moon di Darnassus.", "La General Feathermoon si assicura che tutte le sentinelle abbiano il tempo di pregare Elune. Una vera cacciatrice non brandisce solo la lama, ma anche i doni della dea per sconfiggere i nostri nemici.\n\nPuoi aiutarmi con i miei compiti quotidiani. Posiziona sentinelle in giro per la città: comincia dalle gallerie che portano sotto Cenarion Hold a nord, dalla banca al centro della città, dalla locanda della Craftsman's Terrace a nord-est e dalle porte della città. Le guardie possono aiutarti.\n\nC'è qualcosa che non va a Teldrassil: dobbiamo restare vigili.", nil, "Ti ringrazio per il tuo aiuto. Anche se trovo pace nei rituali quotidiani, è bello avere un momento per riflettere.", 0xf4253869, 0xe7a28828, 0x37765008, nil, 0x026be8bd, "...m." },
  [98071] = { "Il mestiere del birraio", "Consegna le bottiglie di Fallrook Varietal a Dun Garok, nel sud-est delle Hillsbrad Foothills, e riporta un sacco del loro Homebrew Hops.", "Ho combinato un piccolo scambio con i fratelli birrai di Dun Garok. A quanto pare non siamo gli unici a rimpiangere i vigneti della famiglia Fallrook! Le annate migliori sono state bevute da tempo, ma abbiamo ancora casse di vino in cantina.\n\nPorta questa cassa di Fallrook Varietal a Dun Garok, a sud-est, e lasciala presso il focolare dove si radunano, in fondo al loro forte.\n\nIn cambio, riporta con te un sacco di Homebrew Hops.\n\nQuella fortezza è quanto di più simile a casa ci sia da queste parti!", nil, nil, 0xdbd8fe1c, 0xad567a8c, 0xe5403776, nil, nil, "...mm" },
  [98072] = { "I coccodrilli del cielo", "Raccogli 8 Pristine Crimson Scales e portale a James Halloran, a Menethil Harbor.", "Sei proprio intraprendente! Ho solo un altro favore da chiederti, se te la senti di fare qualcosa di un po' più pericoloso.\n\nIl commercio di crocolischi rende bene, ma è poca cosa rispetto a quanto fruttano le scaglie di cucciolo di drago. La gente paga oro per un sacco di quelle.\n\nI coccodrilli del cielo, li chiamo io! Il mio apprendista non riuscirebbe mai a procurarle, ma sembra proprio il lavoro adatto a te!\n\nTroverai i cuccioli molto a est, lungo la Green Belt. Ma fa' attenzione, su quelle colline ci sono orchi pericolosi!", nil, nil, 0x3db2cf68, 0xba342fd8, 0x793428d8, nil, nil, "...mm" },
  [98095] = { "Punti di osservazione preziosi", "Il Deathstalker Masoj ti chiede di posare le tre Apothecary Vials sulle vette attorno alle Hillsbrad Foothills e di tornare da lui.", "Il nostro alto comando inserisce truppe strategiche usando i cavalcapipistrelli. Alcuni punti chiave attorno alle colline hanno perso i loro fari di segnalazione.\n\nPrendi queste fiale. Stappale in tre luoghi: sulle colline al confine con Dun Garok, sull'altopiano che domina la Dunholde Keep e, l'ultima, sul crinale dell'Headland sopra la città di Hillsbrad. I vapori che ne usciranno saranno per i sensi dei pipistrelli come un potente diapason, e li attireranno di nuovo ai punti di sbarco desiderati.\n\nCerca le fiale vuote schiacciate e rinnova i nostri segnali.", nil, nil, 0x9e9c3c95, 0xa522d3ad, 0xde0f6623, nil, nil, "...mm" },
  [98155] = { nil, "Porta $N1 Pristine Pesterhide Pelts a Kristy Grant.", "Le iene Pesterhide di Thousand Needles hanno i manti più splendidi. Non ho mai visto una pelliccia di una tonalità così brillante in tutti i miei viaggi!\n\nVorrei mandare alcune pelli alle mie sorelle a Stormwind, perché so che potrebbero ricavarne qualcosa di incredibile.\n\nNon ho alcuna esperienza di combattimento, quindi ti sarei molto grata se potessi raccogliere qualche pelle di Pesterhide al posto mio.", nil, nil, nil, 0x5d7bef18, 0x023d45ab, nil, nil, "m..mm" },
  [98156] = { "Pelli intatte impacchettate", "Porta il Package of Pristine Pelts a Kimberly Grant.", "{name}, mi sei <stato/stata> così d'aiuto che mi dispiace chiederti un altro favore. Passerà del tempo prima che io possa tornare a casa, a Stormwind. Mi chiedevo se ti dispiacerebbe consegnare queste pelli alle mie sorelle al posto mio.\n\nSono sicura che tornerai lì prima di me. Ti prego, consegna queste pelli alle mie sorelle Kelly e Kimberly, a Stormwind. Di solito si trovano nel Park.", nil, nil, 0x702cae31, 0x518a3bbe, 0x39319c08, nil, nil, "...mm" },
  [98189] = { "Restituire la statuetta", "Porta la Menethil Statuette al Captain Stoutfist, nel Menethil Keep.", "Santo cielo, è... è bellissima!\n\nLa Blind Princess doveva consegnarla a Menethil Harbor prima che accadesse la tragedia. Eravamo così vicini!\n\nCredo che dovesse essere firmata dal Captain Stoutfist, nel Menethil Keep proprio dietro di noi. Perché non hai tu l'onore di portare a termine il lavoro?", nil, nil, 0x6359787c, 0x0c8c34af, 0x67af9a56, nil, nil, "...mm" },
  [98190] = { "Un amico di famiglia", "Porta la Menethil Statuette all'Highlord Bolvar Fordragon, nella Stormwind Keep.", "Dovrai portarla subito a Stormwind. Per quanto io sia fiero che questa fortezza e questo porto portino il nome di re Terenas Menethil II, siamo un porto tranquillo in mezzo a una bruttissima tempesta di nemici. Qui non è sicuro.\n\nI Dragonmaw in particolare sacrificherebbero molto per razziare una cosa del genere... e rabbrividisco al pensiero di cosa ne farebbero.\n\nNon perdere tempo a risalire la catena di comando stavolta, <ragazzo/ragazza>. Va' <dritto/dritta> dall'Highlord Fordragon. Lui saprà dove custodirla al meglio.", nil, nil, 0xd13a5ecd, 0xb560772b, 0xcc6c0655, nil, nil, "...mm", nil, nil, 0x8176cdb8, nil, nil },
  [98191] = { "Un amico di famiglia", "Porta la Menethil Statuette a Lord Grayson Shadowbreaker, nella Cathedral of Light.", "Re Terenas era un brav'uomo. Un uomo devoto. Amato dal suo popolo, e la vera ragione per cui esiste questa alleanza.\n\nL'ironia è che era umile: detestava questo genere di memoriali, e così ne esistono pochissimi. E di quelli, pochi sono sopravvissuti alla caduta di Lordaeron.\n\nSembra che la Luce si sia concentrata in questa statuetta. Sarebbe meglio custodirla nella Cathedral of Light, in Cathedral Square, al centro della città. Portala a Lord Grayson Shadowbreaker perché la custodisca.", nil, nil, 0xd13a5ecd, 0x89dd523c, 0x35ad547b, nil, nil, "...mm" },
  [98208] = { "Il fiore dei cieli", "Recupera il Nord'el per Sylessa Duskwhisper, a Menethil Harbor.", "Sono venuta a Menethil Harbor da Auberdine, dal grande albero Teldrassil, per recuperare un fiore di grande importanza per il mio popolo.\n\nLa nave del mio popolo, la Flying Osprey, naufragò qui molte lune fa, insieme alla Kul Tiran Third Fleet. Tra il suo carico c'era il fiore noto come Nord'el, Bloom of the Heavens nella tua lingua, sbocciato sotto la luna piena sulla vetta del Mount Hyjal, la nostra antica dimora.\n\nTi prego, aiutami a recuperarlo! Il relitto si trova appena a sud della città, ma è abitato da feroci predoni murloc!", nil, nil, 0x67289a3e, 0x145af630, 0xc0d3a012, nil, nil, "...mm" },
  [98209] = { "Il fiore dei cieli", nil, nil, nil, nil, 0x67289a3e, nil, nil, nil, nil, ".mmmm" },
  [98219] = { "Il tenente caduto in disgrazia", "Parla con il tenente Farren Orinelle a Southshore, nelle Hillsbrad Foothills.", "Grazie ancora per aver consegnato la statuetta sana e salva, {name}.\n\nMi servirebbe il tuo aiuto per un'altra cosa. C'è un membro della guardia cittadina che è stato riassegnato a Southshore, nelle Hillsbrad Foothills.\n\nSuo padre era un mio amico, e anche se non nego che la lezione gli serva... vorrei comunque vederlo riuscire. Gli farebbe davvero bene avere qualcuno come te ad aiutarlo.\n\nC'è una nave che può portarti da quelle parti da Menethil Harbor, se ripassi da lì.", nil, nil, 0xc567588f, 0x4c7ba953, 0xc1f837e2, nil, nil, "...mm" },
  [98221] = { "Dalle ceneri", "Il capitano Stoutfist, nella Menethil Keep, vuole che distruggi i 4 set di Attack Plans all'Angerfang Encampment.", "Durante la seconda guerra i Dragonmaw costruirono una flotta proprio dove ci troviamo ora, con l'intento di prendere Hillsbrad. Ci riuscirono quasi!\n\nFurono messi in rotta dai draghi rossi, ridotti a pochi superstiti nel profondo delle montagne. Tuttavia, c'è stata un'impennata di attività nel loro accampamento a nord-est di Menethil.\n\nDun Algaz è la prova che intendono marciare di nuovo in guerra e riprendersi questa terra. Trova i loro piani d'attacco, prendi nota di qualsiasi informazione cruciale e distruggili. Dobbiamo sapere dove colpiranno la prossima volta!", nil, nil, 0x08a75e96, 0x18b3d712, 0xa9a35620, nil, nil, "...mm" },
  [98223] = { "Vecchie abitudini", "Porta il Tattered Spellbook al capitano Stoutfist, a Menethil Harbor.", "Questo libro è stato gravemente bruciato, forse dal fuoco di drago che ha distrutto gran parte del clan Dragonmaw.\n\nDal poco che è leggibile, sembra descrivere rituali legati all'uso della Demon Soul che il clan aveva usato per controllare i draghi.\n\nÈ troppo incompleto per essere davvero utile, ma da alcune pagine di pelle d'animale inserite alla buona sembra che Nek'rosh abbia tentato di recuperarlo. Inchiostro asciugato da poco menziona un \"Shadow Council\".\n\nIl capitano Stoutfist, a Menethil Harbor, vorrà saperlo.", nil, nil, 0x75c9f241, 0x3bf963b0, 0xe438fb44, nil, nil, "...mm" },
  [98230] = { "Questa terra era la loro terra", "Trova Howin Kindfeather a est di Menethil Harbor, lungo la strada.", "Dopo la guerra dei tre martelli, che fece a pezzi la vita nanica come la conoscevamo, i Wildhammer si stabilirono qui, fondando la fortezza montana di Grim Batol.\n\nEra un luogo meraviglioso. Grifoni volteggiavano ovunque guardassi, tuffandosi tra le paludi per afferrare un pesce.\n\nPurtroppo non durò a lungo.\n\nHowin Kindfeather è uno dei primi Wildhammer a tornare da secoli. Se ne sta per conto suo, lontano dal paese. Segui la strada verso est: prima o poi lo troverai. Di certo gli farebbe comodo una mano.", nil, nil, 0x5ef5a781, 0x920b4ded, 0xb7089ef8, nil, nil, "...mm" },
  [98240] = { "Consegna della Crimson Crate", "Porta la Crimson Crate a Howin Kindfeather, appena fuori dalla strada a est di Menethil Harbor.", "La voce su quei cuccioli di drago si è sparsa ufficialmente, {name}. Abbiamo già un ordine!\n\nTe li impacchetto per bene, poi tu li porti al cliente. Lo so, lo so: è solo un ultimo favore, lo prometto!\n\nSono per un certo \"Howin Kindfeather\". Ha mandato in paese il suo grifone, figurati, con una lettera per l'ordine! Dice che si trova appena fuori dalla strada a est, un po' oltre il Whelgar's Excavation Site, se lo conosci.", nil, nil, 0xed839e17, 0xdfb38dba, 0x708169ee, nil, nil, "...mm" },
  [98247] = { nil, "Consegna la Shipping Label a qualcuno al centro commerciale dell'Azeroth Commerce Authority, nelle Redridge Mountains.", "<Sul fianco della cassa, ora piena, si trova un'etichetta di spedizione strappata. Anche se il nome del destinatario è stato strappato, i dettagli sulla provenienza sono ancora leggibili.\n\n\"Proprietà dell'Azeroth Commerce Authority. Si prega di restituire le casse vuote o le spedizioni non consegnate al nostro centro commerciale locale all'incrocio di Three Corners, nelle Redridge Mountains. I corrieri saranno ricompensati per il tempo e il viaggio.\"\n\nAccanto al testo c'è una mappa disegnata alla buona della zona vicino alla destinazione indicata.>", "Ah, salute! Come posso esserti utile?", "Sei <arrivato/arrivata> nel posto giusto! Sono lieto di registrarti come uno dei nostri affiliati. Nessun contratto da firmare e nessun impegno che ti appesantisca. Tutto ciò che ti chiediamo è la diligenza di aiutarci a completare o restituire qualsiasi nostra consegna tu trovi durante i tuoi viaggi.\n\nQuando lo farai, sarai <ricompensato/ricompensata> con il Merchant's Favor, che ti permetterà di acquistare i beni e i servizi che offriamo qui. Anzi, eccone un po' per cominciare.\n\nOra, hai per caso la cassa da cui proviene questa?", nil, 0x2c55cb98, 0x6fa4ac5c, 0xafcd45d6, 0xa89e1ba0, "m...." },
  [98251] = { "Non tornerà mai più", "Uccidi $N1 Shadowhorn Stag e $N2 Ashenvale Bear e torna da Va'xug Firefure, a nord-ovest del Fallen Sky Lake.", "Gaaah!\n\nSono così arrabbiato. Dicevano che Ashenvale era facile da percorrere. Facile per chi? Per le bestie? Per gli uccelli?\n\nUn momento stavo raccogliendo un'erba, quello dopo sono intrappolato in questo burrone. Devo davvero fare il giro di mezza foresta per tornare dove mi trovavo pochi istanti fa?\n\nQuando sono così, i miei incantesimi diventano instabili e si comportano... diversamente.\n\nPotresti sfoltire la fauna qui intorno? Persino i loro stupidi zoccoli mi danno sui nervi. Detesto questa foresta maledetta.", nil, nil, 0xda72cb7d, 0x793d1806, 0xd2c43c4c, nil, nil, "...mm" },
  [98252] = { "Un sentiero del vuoto", "Mostra all'Eye of Kilrogg di Va'xug la strada per tornare alla via principale di Ashenvale.", "Mostra al mio Eye of Kilrogg la via d'uscita da questo burrone e il ritorno alla strada di Ashenvale. Tienilo in movimento e io ti seguirò appena vedrò un sentiero libero.\n\nIo resterò qui: uno di noi deve mantenere l'orientamento. Se perdi la strada, posso guidarti indietro attraverso l'occhio. Non voglio che vaghiamo entrambi alla cieca in questa foresta maligna.\n\nPosso mantenere il canale per quattro minuti. Non di più. Raggiungi la strada prima che la visione si spezzi, oppure torna da me e riproveremo.", nil, nil, 0x9e802cef, 0x41338fb7, 0xbaa5cde3, nil, nil, "...mm" },
  [98282] = { "Rischi alchemici", "Raccogli un Unruptured Stalker Gland al Thelgen Rock per Caitlin Grassman, a Menethil Harbor.", "Certe ricette alchemiche richiedono ingredienti provenienti da, be', posti molto pericolosi. E spesso sono solo le erbe di base! Gli altri ingredienti sono anche peggio!\n\nDevo preparare altro antiveleno prima di poter ripartire. Giuro che tutto in questa palude è velenoso. È come se il veleno scorresse nella terra stessa!\n\nPuoi aiutarmi? Mi servirà una ghiandola velenifera dei ragni del Thelgen Rock, molto a sud-est. Ma deve essere intatta, altrimenti ne uscirà troppo veleno prima che tu arrivi qui. Scusa!", nil, nil, 0x67b679f7, 0xac87cb29, 0xd937715e, nil, nil, "...mm" },
  [98284] = { "Campeggio 101: Enchanting", nil, "Gli incantatori rendono tutto migliore e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. È così importante trovare un po' di svago durante il riposo, e questo pizzico di magia può aiutarti a essere <pronto/pronta> ad affrontare ogni sorta di sfida quando tornerai sulla vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [98285] = { "Campeggio 101: Engineering", nil, nil, nil, nil, 0x1cb4025b, nil, nil, nil, nil, ".mmmm" },
  [98286] = { "Campeggio 101: Enchanting", nil, "Gli incantatori rendono tutto migliore e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. È così importante trovare un po' di svago durante il riposo, e questo pizzico di magia può aiutarti a essere <pronto/pronta> ad affrontare ogni sorta di sfida quando tornerai sulla vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [98287] = { "Campeggio 101: Engineering", "Parla con Sprite Jumpsprocket a Stormwind per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli ingegneri come te sanno inventare ogni sorta di aggeggi, robot e bombe, per divertimento e per profitto.\n\nConosco qualcuno che può insegnarti a creare un Reagent Bot per il tuo accampamento. Questo utile automa può tenerti ben rifornito, così che tu e i tuoi alleati non restiate mai senza i materiali necessari per alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xba6c8a24, 0x549b28c0, nil, nil, "...mm" },
  [98293] = { "Disarmo forzato", "Raccogli $N1 Dragonmaw Armaments al Dragonmaw Retreat, poi portali al capitano Stoutfist, nella Menethil Keep.", "I Dragonmaw stanno ammassando armi di ogni genere. Sarebbe saggio sottrargliele prima che altri soldati possano armarsi.\n\nIl capitano Stoutfist, nella Menethil Keep, sarebbe di certo interessato.", nil, nil, 0xe87e8bcf, 0xa648dc25, 0x494ec9da, nil, nil, "...mm" },
  [98300] = { "Un messaggio per Ironforge", "Consegna l'Howin's Missive a re Magni Bronzebeard, a Ironforge.", "Il mio lavoro qui è tutt'altro che finito, {name}. E devo mandare notizie a mia moglie Claira, ad Aerie Peak, e aggiornare anche Falstad.\n\nMa sono affari miei. Affari dei Wildhammer.\n\nDetto questo, dovresti informare di tutto questo anche re Magni Bronzebeard, a Ironforge. Le Wetlands sono a un tiro di sasso dalle sue terre, e niente di ciò che succede qui è una buona notizia da avere alle porte di casa. Questa lettera dovrebbe bastare.\n\nPuoi tornare passando per Dun Algaz o volare da Menethil Harbor per arrivare a Ironforge.", nil, nil, 0x70a6616f, 0x4ae70287, 0x38f01d76, nil, nil, "...mm" },
  [98310] = { "Raccogliere il nostro futuro", "Usa la Goaz Stone vicino ad Ados, Modr, Golm e Neru e riporta i loro cuori al Prospector Whelgar.", "Ci sono altri golem, più grandi, in tutte le Wetlands. Ognuno reca iscrizioni che li indicano come Ados, Modr, Golm e Neru: corrispondono ai pezzi mancanti della Goaz Stone che hai trovato!\n\nScommetto che se riusciamo a portare anche dei pezzi di loro, riveleremo di più della Goaz Stone!\n\nTroverai Ados ai Dragonmaw Gates, a est, vicino a Grim Batol. Modr è proprio fuori da Dun Modr, a nord. Golm si trova sotto Grim Batol, a est di Dun Algaz. Neru è dietro Direforge Hill, a nord-est.", nil, nil, 0x9ceacfd8, 0xe9da4d7c, 0x81be163b, nil, nil, "...mm" },
  [98313] = { "Per ulteriori studi", "Porta il Whelgar Relic Package allo Historian Karnik, a Ironforge.", "Qualunque cosa sia, {name}, è roba epica, poco ma sicuro.\n\nTi impacchetto tutto per bene. Portalo allo Historian Karnik, nella Hall of Explorers di Ironforge. Di solito lo trovi in fondo, con il naso infilato in qualche tomo nella biblioteca.\n\nCi vorrà un vero esercito per risolvere questo caso, ma se ciò che abbiamo visto finora vale qualcosa, ne varrà davvero la pena!", nil, nil, 0x89f4c96b, 0x0134cc07, 0x00b268a2, nil, nil, "...mm" },
  [98319] = { "Mettere in sicurezza la montagna", nil, nil, nil, nil, 0xe669cbf4, nil, nil, nil, nil, ".mmmm" },
  [98321] = { nil, "Raccogli $N1 Flintfire Shipments nella Grizzled Den per Tongus Flintfire, a Kharanos.", "Oha! Che bello vedere un {race} che non ha paura di sporcarsi le mani.\n\nSe cerchi lavoro, temo di essere un po' a corto di rifornimenti al momento. La nostra fonte di minerale più affidabile è stata invasa dai wendigo e ora la caverna è abbandonata. I minatori hanno dovuto mollare tutto quando sono fuggiti!\n\nSenti, perché non vai a dare un'occhiata nella Grizzled Den, a ovest, e vedi se trovi qualcuna delle nostre spedizioni perdute? Ci risparmierebbe un sacco di guai.", "I wendigo sono bestiacce cattive. Meno male che tutti i minatori sono usciti dalla Grizzled Den tutti interi!", "Ecco, così va meglio! Con queste spedizioni rimetteremo in funzione la forgia in un attimo!", nil, 0xffee5126, 0xa4bbc762, 0x9fbc2026, 0x45d32722, "m...." },
  [98322] = { "Mettere in sicurezza la montagna", "Va' a vedere come sta la Mountaineer Gretchen, a ovest di Kharanos.", "Esplorare caverne buie è roba da avventurieri. Il mio lavoro è solo stilare rapporti e mandarli a Ironforge.\n\nIl guaio è che uno dei miei rapporti non è... be', rientrato. Ho chiesto ad alcuni montanari di saperne di più sul problema dei wendigo che abbiamo qui, ma non ho avuto loro notizie.\n\nVisto che sei già in giro, che ne dici di passare dalla Mountaineer Gretchen, appena a ovest del paese? Sono già abbastanza in ritardo così!", nil, "Ti manda il vecchio Whitebeard, eh?\n\nIl suo rapporto l'ho ricevuto, eccome. Tutta questa situazione è un disastro!", 0xe669cbf4, 0x7154065a, 0xbebd5727, nil, 0xef2ba3dc, "...m." },
  [98323] = { "Mettere in sicurezza la montagna", "Riporta il Mountaineer Gretchen's Report a Senir Whitebeard, a Kharanos.", "Spero che tu abbia abbattuto un bel numero di quei bastardi mentre eri là dentro. Peccato per Cornelius, però.\n\nDa quello che mi hai descritto, non c'è molto da riferire se non che la caverna è una causa persa. A Whitebeard non piacerà la risposta, ma non oso mandare nessun altro in quella trappola mortale.\n\nSentiti <libero/libera> di riferire il messaggio, {name}. Io non mi muovo da qui finché la montagna non sarà sicura.", "Ah, sei <tornato/tornata> giusto in tempo.\n\nChe c'è, <ragazzo/ragazza>? Sembra che tu abbia visto un fantasma.", "Completamente invasa? Perché non mi sorprende.\n\nBe', finirà anche questo nel rapporto.\n\n<Senir piega la lettera di Gretchen e la infila nella sua pila di appunti.>", 0xe669cbf4, 0x2405aa8a, 0xd096a625, 0x547dd283, 0x0cf43582, "....." },
  [98326] = { nil, "Uccidi Frosthowl e raccogli il Sack of Fish per Gretta Ganter, a Brewnall Village.", "Lo sai quanto è difficile pescare su un lago ghiacciato? Il mio povero marito, Paxton, è là in mezzo da giorni e abbiamo a malapena un sacco da mostrare.\n\nBe', avevamo un sacco da mostrare. Finché quel dannatissimo wendigo non mi ha aggredita e si è portato via il nostro bottino. Ci vorranno settimane per ripescare tutto! Sempre che quel chiassone di Frosthowl non li abbia fatti scappare tutti.\n\nFacci un favore e riportacelo, eh? Quel bruto sbavante si nasconde da qualche parte nel profondo della Grizzled Den, a sud-est.", "Farà caldo a Dun Morogh prima che io dica a Paxton di aver perso tutta la sua scorta per colpa di un wendigo.", "Mi hai salvato la vita, {name}!\n\nMio marito ci avrebbe riso sopra, ma non sopportavo di dirgli che doveva passare un'altra notte sul lago. Forse ora potremo goderci un vero banchetto.", nil, 0xea44c644, 0xbf80aad5, 0x9511dc93, 0x0c56d569, "m...." },
  [98340] = { "Il grande spirito felino", "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.", nil, nil, nil, 0xb22fd0a9, 0x127a78ca, nil, nil, nil, "..mmm" },
  [98341] = { "Il grande spirito felino del vento", "Cerca l'Avatar of Saeyleenan nella parte meridionale di Moonglade e scopri cosa ha da insegnarti sulla natura del felino del vento.", "Uno spirito della tua terra natale è apparso qui di recente e mi ha chiesto di guidarti da lui. Questo spirito felino del vento è venuto per istruirti e guidarti, affinché tu possa assumere la forma felina dello spirito di Zephras.\n\nTutti i druidi prima o poi cercano questa saggezza, anche se sembra che la tua terra natale abbia una forma un po' diversa dalla nostra tradizionale. Se desideri assumere la forma felina di questo spirito, dovrai affrontare la nostra prova.\n\nLo troverai nella parte meridionale di Moonglade, a sud dei ponti gemelli.", nil, nil, 0x802a0775, 0xa9c77684, 0xb2eb4e2f, nil, nil, "...mm" },
  [98342] = { "Il grande spirito felino", nil, nil, nil, nil, 0xb22fd0a9, nil, nil, nil, nil, ".mmmm" },
  [98372] = { "Una fine sfortunata", nil, nil, nil, "Il Night Watchman morto che giace davanti a te è coperto di squarci e tagli profondi. È evidente che è stato sbranato da qualche grossa bestia.\n\nNoti che il cadavere stringe in mano una torcia spenta. Ti chini e la strappi dalle sue dita irrigidite. Potrebbe tornarti utile nei tuoi viaggi per Duskwood e oltre, per rivelare ciò che l'oscurità nasconde.", 0xc0c4b3d4, nil, nil, nil, 0x10acb436, ".mmm." },
  [98386] = { "L'Alther's Mill", "Uccidi $N1 Greater Tarantula e distruggi $N2 Tarantula Eggs ad Alther's Mill per il Foreman Oslow, a Redridge.", "Orchi, gnoll, murloc. Sembra che tutto voglia impedirmi di finire questo ponte in tempo. Ora ci arriva voce che la nostra segheria è infestata dalle tarantole!\n\nSe vuoi guadagnare qualche moneta in più, andresti all'Alther's Mill, a est, a risolvere il loro problema di ragni? Quel posto per me è praticamente inutile se non posso mandarci gli operai in sicurezza a ritirare le spedizioni.\n\nAh, e se vedi il vecchio Alther, digli che mi deve qualcosa per aver ripulito il suo disastro.", nil, "La segheria è messa così male? È peggio di quanto pensassi.\n\nNon sono particolarmente schizzinoso, ma il lavoro è già abbastanza duro senza ragni che mi portano via gli operai. Grazie per l'aiuto, {name}!", 0xe7ba8f99, 0x7745e897, 0xebb117bb, nil, 0x4d3ec210, "...m." },
  [98387] = { "Il blocco dei Blackrock", "Porta $N1 Stolen Weapons e $N2 Blackrock Supplies al Marshal Marris, a Lakeshire.", "Non si può combattere una guerra senza armi.\n\nAnche se gli orchi Blackrock hanno invaso queste terre, i loro sfacciati sforzi non sono privi di punti deboli.\n\nDirigiti a sud-est, sotto la Stonewatch Keep, trova i loro accampamenti e prendi di mira le loro armi e i loro rifornimenti.\n\nVedremo quanto saranno minacciosi senza i loro strumenti di guerra.", "Gran parte di ciò che troverai sarà comunque stato razziato a Lakeshire. Mi farà bene sapere che la nostra gente prospererà mentre gli orchi appassiscono.", nil, 0xaf4ac457, 0x49a066b7, 0x2b169b79, 0x5ee2dc22, nil, "....m" },
  [98391] = { "La sorellanza di Elune", "Parla con Sister Aquinne, a Darnassus.", "Benedizioni a te, {class}. La sorellanza di Elune è un pilastro della società kaldorei da migliaia di anni.\n\nPrima della grande frattura, prima della guerra degli antichi, attraverso la lunga veglia, abbiamo guidato e curato il nostro popolo nell'oscurità. Questo è il nostro compito, e questo è ciò che esige l'impareggiabile madre luna.\n\nOra abbiamo bisogno del tuo aiuto in una questione di grande importanza. Sister Aquinne attende il tuo arrivo a Darnassus.", nil, "Sono lieta che tu sia <arrivato/arrivata> così in fretta. La sorellanza ha bisogno del tuo aiuto.", 0xbbe6a9b4, 0x1f3d24f5, 0xd260a541, nil, 0x0410d1a8, "...m." },
  [98392] = { "Oscurità nella radura", "Raccogli l'Hatescreech's Amulet, il Windmistress Gaedress' Amulet e il Witchmother Arysa's Amulet per la Sentinel Arynia Cloudsbreak, nell'Oracle Glade.", "Queste cinture... guarda bene il cuoio, {name}. Vedi la contaminazione che scorre tra le fibre?\n\nHo un sospetto sulla sua origine, ma ci serviranno altre prove per esserne sicuri.\n\nTorna nei nidi delle arpie a ovest ed elimina le loro capo. Se le loro collane portano la stessa oscurità di queste cinture, avremo la nostra risposta.", "Hai strappato gli amuleti alle capo delle arpie?", "<Arynia esamina gli amuleti.>\n\nVedi quei vortici verdi immondi dentro le gemme? È davvero opera della corruzione del fel moss.\n\nHo sentito rapporti simili da Shadowglen e da altre zone tra i rami, di questa sostanza che rivolge il nostro stesso mondo contro di noi.\n\nInformerò subito i miei superiori.", 0xaad1e9ab, 0xab3da6db, 0x662c4561, 0x5c33eda2, 0x1d4da464, "....." },
  [98393] = { "Il grande spirito felino", "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.", nil, nil, nil, 0xb22fd0a9, 0x127a78ca, nil, nil, nil, "..mmm" },
  [98394] = { "Il grande spirito felino", "Cerca il Great Cat Spirit nella parte meridionale di Moonglade e scopri cosa ha da insegnarti sulla natura del felino.", "Nella parte meridionale di Moonglade, su una collina che domina il ponte, dimora un essere saggio e astuto che chiamiamo il Great Cat Spirit.\n\nCome il Great Bear Spirit, questo spirito ha fatto da maestro e guida ai druidi che desiderano assumere la forma felina. Tutti i druidi prima o poi cercano la sua saggezza, e se desideri assumere la forma di un felino, lo farai anche tu.\n\nVa' a incontrare il Great Cat Spirit e impara ciò che ha da insegnarti.", nil, nil, 0xb22fd0a9, 0x75cdb0e3, 0x65936190, nil, nil, "...mm" },
  [98396] = { "Il grande spirito felino", nil, nil, nil, nil, 0xb22fd0a9, nil, nil, nil, nil, ".mmmm" },
  [98397] = { nil, "Torna a Darnassus e parla con Mathrengyl Bearwalker, nel Cenarion Enclave.", nil, nil, nil, nil, 0x17d4d4c5, nil, nil, nil, "m.mmm" },
  [98403] = { "Odio contorto", "Uccidi $N1 Befouled Webwood e porta il Mature Fel Moss di Xethorr the Wicked a Tallonkai Swiftroot, a Dolanaar.", "Lord Melenas non ha agito da solo; obbediva agli ordini di un altro. Colui che cerchi è Xethorr the Wicked. Sembra che abbia corrotto i ragni che vivono su Teldrassil, destinando il loro veleno a qualche piano immondo.\n\nSi è stabilito nel profondo della foresta, nella zona a nord-ovest di qui nota come the Cleft. Fa' attenzione e porta degli alleati, perché con Xethorr non si scherza.\n\nElimina la sua progenie e portami tutto ciò che possa dirci di più sull'opera del satiro qui.", "<Tallonkai abbassa la voce.>\n\nXethorr cammina ancora libero?", "Avrei dovuto sapere che veniva usato per corrompere i ragni di questa terra.\n\nHo sentito sussurrare che questa sostanza è la fonte di gran parte della corruzione che ci affligge. Anche se non è l'originale, è un campione più vecchio e potrebbe fornire più informazioni di quante ne abbiamo ottenute finora.\n\nDi solito ti farei mandare questo a Darnassus per ulteriori studi. Tuttavia, per il momento è meglio tenere la cosa nascosta, o Dolanaar non recupererà mai la sua reputazione.\n\nConfido che tu faccia lo stesso.", 0x10738b8e, 0xa891e626, 0x8a01b9a3, 0x32ad7205, 0x7c0c6469, "....." },
  [98404] = { "Il grande spirito felino del vento", nil, nil, nil, nil, 0x802a0775, nil, nil, nil, nil, ".mmmm" },
  [98405] = { "Il grande spirito felino", "Cerca il Great Cat Spirit nella parte meridionale di Moonglade e scopri cosa ha da insegnarti sulla natura del felino.", "Nella parte meridionale di Moonglade, su una collina che domina il ponte, dimora un essere saggio e astuto che chiamiamo il Great Cat Spirit.\n\nCome il Great Bear Spirit, questo spirito ha fatto da maestro e guida ai druidi che desiderano assumere la forma felina. Tutti i druidi prima o poi cercano la sua saggezza, e se desideri assumere la forma di un felino, lo farai anche tu.\n\nVa' a incontrare il Great Cat Spirit e impara ciò che ha da insegnarti.", nil, nil, 0xb22fd0a9, 0x75cdb0e3, 0x65936190, nil, nil, "...mm" },
  [98407] = { "Prova di forza", "Raccogli $N1 Spiked Collars dai Redridge Thrasher per il Deputy Feldon, vicino a Lakeshire.", "Se gli gnoll sono diventati così audaci da accamparsi così vicino agli umani, chissà fin dove si spingeranno. Dobbiamo scoraggiarli.\n\nLe bestie sono tutt'altro che organizzate, ma sembrano rispettare la forza più di ogni altra cosa. Se riusciamo a uccidere i peggiori, magari prendendo qualche loro trofeo, ricorderemo a questi gnoll perché dovrebbero restare sulle colline, dove è il loro posto.\n\nSe vedi qualcuno dei loro thrasher, portami i loro collari. Dovrebbe rimettere loro addosso la paura dell'Alleanza.", "Una valutazione completa degli gnoll non può dirsi tale senza affrontare i peggiori della loro specie. Abbatti quei thrasher!", "Ne hai proprio una bracciata.\n\nAnche se questo non risolve il nostro problema qui fuori, posso stare tranquillo sapendo che li abbiamo scoraggiati dallo spingersi oltre. Ottimo lavoro, {name}.", 0xaf8e550f, 0xed3fd63d, 0x0a358c18, 0xfa2277b4, 0x4cf4331d, "....." },
  [98423] = { "Il Treaty of Understanding", "Consegna il Treaty of Understanding a Magni Bronzebeard, a Ironforge.", "Dentro la cripta trovi una tavoletta che riporta i termini di un trattato di pace tra i clan nanici Bronzebeard e Wildhammer. Sembra risalire al periodo subito dopo la guerra dei tre martelli, ed è molto probabilmente un pezzo notevole della storia nanica. Il re di Ironforge sarebbe senz'altro interessato a questo manufatto.", "Cosa hai portato dalle profondità, {class}?", "Ah sì, il mio antenato Madoran fu il primo re Bronzebeard di Ironforge dopo la grande guerra civile tra i clan Wildhammer, Bronzebeard e Dark Iron. Questo trattato fu redatto per sancire la fine delle ostilità e le condizioni di pace dopo che i Bronzebeard conquistarono la montagna.\n\nCome vedi, i Wildhammer e i Bronzebeard lo firmarono... e i Dark Iron no.\n\nGrazie per averlo recuperato e avermelo portato, {class}.", 0xf42ec125, 0x9c2002f0, 0xcb3b413b, 0xdcf587b9, 0xd29d5f82, "....." },
  [98447] = { "La famiglia Valor", "Scopri la causa dei fantasmi della famiglia Valor a Raven Hill per Sirra Von'Indi, a Darkshire.", "Nonostante tu abbia placato i fantasmi della famiglia Valor, le segnalazioni di aggressioni non sono cessate. Era una buona scommessa, ma forse non abbiamo davvero risolto le loro faccende in sospeso.\n\nDalle mie ricerche, sembra che questa famiglia sia scomparsa tutta nello stesso momento. Qualunque trauma abbia incatenato i loro spiriti a questo mondo dev'essere avvenuto tutto in una volta.\n\nIl nostro unico indizio è il luogo in cui hai trovato il libro. Torna a Raven Hill e vedi cosa riesci a trovare. Forse portare le loro armi risveglierà qualcosa.", nil, nil, 0x27a57039, 0x5a0bdeb9, 0x839ba7ea, nil, nil, "...mm" },
  [98459] = { "Una mancanza di virtù", "Consegna il Tom's Gift a Bart Tidewater, a Menethil Harbor, nelle Wetlands.", "Bart Tidewater è un taccagno buono a nulla, te lo dico io!\n\n\"Capitano della Maiden's Virtue\", si fa chiamare. Quella nave ha navigato quanto un sasso a Tanaris! Non è un capitano, è un attore che ha vinto abbastanza mani a poker da comprarsi la Virtue!\n\nSe mai ti trovi a Menethil Harbor, nelle Wetlands, daglielo e digli che viene dal vecchio Half-fish.\n\nC'è una nave da qui che può portarti <dritto/dritta> al porto, tra l'altro. Sarà la seconda fermata!\n\nE bara a poker!", nil, nil, 0x7df3b255, 0x8476eeda, 0xd2b7c232, nil, nil, "...mm" },
  [98461] = { "Amore non corrisposto", "Consegna la Hollee's Note a Tarrel Rockweaver, vicino a Menethil Harbor, nelle Wetlands.", "Se stai lasciando Auberdine, mi servirebbe il tuo aiuto!\n\nIl mio caro amico Tarrel e io eravamo compagni di studi. Oh, era così sveglio in tutto ciò che riguardava gli scavi! Ci siamo separati dopo il diploma: lui nelle Wetlands, io qui a Darkshore.\n\n<Hollee sospira, poi aggrotta leggermente la fronte.>\n\nScusa, e sua moglie... Merrin.\n\nNon importa. Se vai nelle Wetlands, potresti assicurarti che stia bene? E magari dargli questo? Probabilmente è vicino a Menethil Harbor. C'è una nave che va dritta lì.", "Di cosa si tratta?", "<Tarrel legge il biglietto.>\n\nOh... oh cielo. Povera Hollee.\n\nHa sempre avuto un debole per me. E, a dire il vero, c'è stato un tempo in cui l'avrei ricambiata. Ma sono sposato. Felicemente sposato!\n\nCredo che la cosa migliore sia non rispondere. Non so come darle una delusione, e ho cose ben più urgenti di cui preoccuparmi qui! Mia moglie è scomparsa!", 0xb2150b23, 0x7208db43, 0xa9ab1ed6, 0x0d4165b7, 0x82925279, "....." },
  [98517] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [98574] = { nil, "Leggi l'Hallowed Memorandum e parla con Branstock Khalder, ad Anvilmar.", "Mentre mi aiutavi, mi è stato consegnato questo memorandum da passarti. Prenditi il tempo di leggerlo quando puoi. Credo che venga dall'istruttore dei sacerdoti Branstock. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.", nil, nil, nil, 0x9ede68c6, 0xd8ec11c1, nil, nil, "m..mm" },
  [98581] = { nil, "Leggi l'Archaic Rune e parla con Teo Hammerstorm, ad Anvilmar.", "Mentre mi aiutavi, mi è stata consegnata questa runa da passarti. Prenditi il tempo di leggerla quando puoi. Dallo stile Wildhammer di queste iscrizioni, immagino venga dall'istruttore degli sciamani Teo Hammerstorm. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.", "Ah, sei <riuscito/riuscita> a leggere la runa? È intrisa del potere degli elementi grazie a una delle nostre scritture più antiche. Questo dimostra che hai la stoffa del {class}.", "Le arti sciamaniche sono state custodite dal clan Wildhammer per anni, e ora sono passate anche nelle mani dei nani Bronzebeard. Sono qui per aiutare a diffondere questi insegnamenti e guidare i nuovi sciamani che imparano le vie degli elementi. Vieni da me se ti serve altro addestramento negli incantesimi di terra, aria, fuoco e acqua.", nil, 0x2d3d009b, 0x219621d8, 0x274fa608, 0x051e97bc, "m...." },
  [98815] = { "Pelli degli altipiani", "Riporta $N1 Thicket Raptor Hides a James Halloran, il conciatore, a Menethil Harbor.", "Gli altipiani ospitano rovine di qualche tipo, segreti che una squadra di spedizione sta esplorando. Quello che so è che hanno la loro fauna e le loro belve in agguato in quella palude montana. Che ne dici di avventurarti là dentro con qualche amico ben equipaggiato, e facciamo uno scambio?\n\nNon m'importa se si nascondono, voglio le loro pelli! Portami le pelli di quattro Thicket Raptor e ti preparerò uno scambio che ne varrà la pena.", nil, nil, 0xef33826c, 0x2ade49d5, 0xcd74ccdc, nil, nil, "...mm" },
  [98824] = { "Un prisma preistorico", "Porta la Titan Relic all'High Explorer Magellas, nella Hall of Explorers di Ironforge.", "Con iscrizioni simili a quelle dei titani sulle sue facce, nient'altro che la Hall of Explorers di Ironforge è il posto giusto dove portarlo.\n\nMi piace pensare che verrai <citato/citata> nella storia, nel catalogo: \"Recuperato da {name}! Autenticato dal Prospector Whelgar...\" Ah, mi sto lasciando trasportare.\n\nL'High Explorer Magellas ti riceverà e, data la natura squisita di ciò che porti, ti sarà di certo molto generosamente grato se lo donerai al museo.\n\nBella scoperta!", nil, nil, 0xe4e83006, 0xdf91b989, 0x89111dce, nil, nil, "...mm" },
})
